import { StudioProApi, SelectorResult } from "@mendix/extensions-api";
import { Tool } from "../../types/tool";
import { Agent } from "../../types/agent";
import { validateMCPTool, validateMicroflowTool } from "../../utils/toolUtils";
import { ModelDocument } from "../../types/modelDocument";
import { ToolTypes } from "../../constants/mcp";

export const handleValidateTool = async (
    field: keyof Tool,
    tool: Tool,
    agent: Agent,
    studioPro: StudioProApi
): Promise<true | string> => {
    const existingTools: Tool[] = agent.tools;

    switch (field) {
        case "name":
            if (!tool.toolType || tool.toolType === ToolTypes.MCP) {
                // MCP tool names are provided by the MCP server
                break;
            }
            if (!tool.name || tool.name.trim() === "") {
                return "Tool name cannot be empty.";
            }
            if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(tool.name)) {
                return "Tool name must start with a letter or underscore and contain only letters, numbers, and underscores.";
            }
            if (tool.name.length > 64) {
                return "Tool name cannot exceed 64 characters.";
            }
            if (existingTools && existingTools.some((t) => t.name === tool.name && t.id !== tool.id)) {
                return "Tool name must be unique.";
            }
            break;

        case "description": {
            if (!tool.toolType || tool.toolType === ToolTypes.MCP) {
                // MCP tool descriptions are provided by the MCP server
                break;
            }
            if (!tool.description || tool.description.trim() === "") {
                return "Tool description cannot be empty.";
            }
            if (tool.description.length > 4096) {
                return "Tool description cannot exceed 4096 characters.";
            }
            break;
        }

        case "toolType": {
            if (!tool.toolType) {
                return "Tool type cannot be empty.";
            }
            break;
        }

        case "document": {
            if (tool.toolType === ToolTypes.Microflow) {
                return await validateMicroflowTool(tool, studioPro);
            } else if (tool.toolType === ToolTypes.MCP) {
                return await validateMCPTool(tool, studioPro, agent);
            }
            break;
        }

        default:
            return true;
    }
    return true;
};

export const handleSelectDocument = async (
    studioPro: StudioProApi,
    documentTypeId: string
): Promise<ModelDocument | undefined> => {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectDocument({
        allowNone: true,
        query: { elementType: documentTypeId },
    });
    if (selectorResult.status === "ok") {
        return {
            qualifiedName: selectorResult.selected.module + "." + selectorResult.selected.name,
            documentId: selectorResult.selected.id,
        };
    } else if (selectorResult.status === "none") {
        return {
            qualifiedName: "",
            documentId: "",
        };
    }
    return undefined;
};
